# Parse results and calculate proportions per business
from collections import defaultdict

mentions_service = defaultdict(int)
positive_service = defaultdict(int)

for i, r in enumerate(dataset):
    bid = r['business_id']
    result = all_results[i].upper()

    # Check if mentions service
    if 'MENTIONS_SERVICE: YES' in result or ('MENTIONS_SERVICE' in result and '| POSITIVE:' in result and 'MENTIONS_SERVICE: NO' not in result):
        mentions_service[bid] += 1
        # Check if positive
        if 'POSITIVE: YES' in result:
            positive_service[bid] += 1

# Calculate proportion for each business
proportions_broad = {}
for bid in mentions_service:
    if mentions_service[bid] > 0:
        proportions_broad[bid] = positive_service[bid] / mentions_service[bid]

# Sort by proportion (descending)
ranked_broad = sorted(proportions_broad.items(), key=lambda x: x[1], reverse=True)

print("Top 10 businesses by positive service proportion (broad definition):")
for i, (bid, prop) in enumerate(ranked_broad[:15], 1):
    marker = " <-- TARGET" if bid == target_bid else ""
    print(f"  #{i}: {bid} - {prop:.4f} ({positive_service[bid]}/{mentions_service[bid]}){marker}")

# Find target business rank
for i, (bid, prop) in enumerate(ranked_broad, 1):
    if bid == target_bid:
        print(f"\nTarget business rank: #{i} with proportion {prop:.4f} ({positive_service[bid]}/{mentions_service[bid]})")
        break
